<?php
require_once __DIR__ . '/_layout.php';
$id = filter_input(INPUT_GET, 'edit', FILTER_VALIDATE_INT);
$edit = null;
if ($id) { $s = db()->prepare('SELECT announcement_id AS id, announcements.* FROM announcements WHERE announcement_id=?'); $s->execute([$id]); $edit = $s->fetch() ?: null; }
$items = db()->query('SELECT a.announcement_id AS id, a.*, COALESCE(ad.full_name, "Bantay Dagat") author FROM announcements a LEFT JOIN admins ad ON ad.admin_id=a.admin_id ORDER BY a.created_at DESC')->fetchAll();
$categories = ['Bantay Dagat Activities','Coastal Clean-Up Drives','Marine Conservation Programs','Environmental Announcements','Community Activities','Coastal Warnings','Emergency Advisories'];
admin_header('Manage announcements');
?>
<div class="row g-3"><div class="col-xl-5"><form class="surface-card" action="../actions/admin.php" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="save_announcement"><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?>"><h2 class="h6 fw-bold"><?= $edit ? 'Edit announcement' : 'Create announcement' ?></h2><div class="mb-3"><label class="form-label">Title</label><input class="form-control" name="title" maxlength="180" required value="<?= e($edit['title'] ?? '') ?>"></div><div class="mb-3"><label class="form-label">Category</label><select class="form-select" name="category" required><?php foreach ($categories as $category): ?><option <?= ($edit['category'] ?? '') === $category ? 'selected' : '' ?>><?= e($category) ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="7" required><?= e($edit['description'] ?? '') ?></textarea></div><div class="mb-3"><label class="form-label">Featured image</label><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/webp"><?php if (!empty($edit['featured_image'])): ?><div class="help-text mt-1">Current: <?= e(basename($edit['featured_image'])) ?></div><?php endif; ?></div><div class="mb-3"><label class="form-label">Publication status</label><select class="form-select" name="publication_status"><?php foreach (['Draft','Published','Unpublished'] as $publicationStatus): ?><option value="<?= e($publicationStatus) ?>" <?= ($edit['publication_status'] ?? 'Draft') === $publicationStatus ? 'selected' : '' ?>><?= e($publicationStatus) ?></option><?php endforeach; ?></select></div><div class="d-flex gap-2"><button class="btn btn-primary rounded-pill"><?= $edit ? 'Save changes' : 'Add announcement' ?></button><?php if ($edit): ?><a href="manage-announcements.php" class="btn btn-outline-secondary rounded-pill">Cancel</a><?php endif; ?></div></form></div>
<div class="col-xl-7"><section class="surface-card"><h2 class="h6 fw-bold mb-3">Announcements</h2><div class="admin-table-wrap"><table class="table table-hover align-middle"><thead><tr><th>Title</th><th>Category</th><th>Status</th><th>Published</th><th>Actions</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['title']) ?></td><td><?= e($item['category']) ?></td><td><span class="status-pill"><?= e($item['publication_status']) ?></span></td><td><?= e(date('M j, Y', strtotime($item['created_at']))) ?></td><td class="text-nowrap"><a class="btn btn-outline-primary btn-sm" href="manage-announcements.php?edit=<?= (int) $item['id'] ?>">Edit</a><form class="d-inline" method="post" action="../actions/admin.php"><?= csrf_field() ?><input type="hidden" name="action" value="delete_announcement"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="btn btn-outline-danger btn-sm" data-confirm="Delete this announcement?">Delete</button></form></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="5" class="text-secondary">No announcements yet.</td></tr><?php endif; ?></tbody></table></div></section></div></div>
<?php admin_footer(); ?>
